def git(*a):
    r=subprocess.run(['git']+list(a),capture_output=True,text=True)
    return r.returncode,r.stdout,r.stderr
def slim(o,depth=0):
    if isinstance(o,dict):
        r={}
        for k,v in o.items():
            if any(x in k.lower() for x in ('token','secret','credential','auth')): continue
            r[k]=slim(v,depth+1)
        return r
    if isinstance(o,list): return [slim(v,depth+1) for v in o[:4]]
